1	<!DOCTYPE html>
2	<html lang="en">
3	  <head>
4	    <meta charset="utf-8" />
5	    <meta name="viewport" content="width=device-width, initial-scale=1" />
6	    <meta name="csrf-token" content={get_csrf_token()} />
7	    <.live_title default="CleanerCrm" suffix=" · Phoenix Framework" phx-no-format>{assigns[:page_title]}</.live_title>
8	    <link phx-track-static rel="stylesheet" href={~p"/assets/css/app.css"} />
9	    <script defer phx-track-static type="text/javascript" src={~p"/assets/js/app.js"}>
10	    </script>
11	    <script>
12	      (() => {
13	        const systemTheme = () => matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
14	
15	        const setTheme = (theme) => {
16	          if (theme === "system") {
17	            localStorage.removeItem("phx:theme");
18	            document.documentElement.setAttribute("data-theme", systemTheme());
19	            document.documentElement.setAttribute("data-theme-source", "system");
20	          } else {
21	            localStorage.setItem("phx:theme", theme);
22	            document.documentElement.setAttribute("data-theme", theme);
23	            document.documentElement.setAttribute("data-theme-source", "user");
24	          }
25	        };
26	        if (!document.documentElement.hasAttribute("data-theme")) {
27	          setTheme(localStorage.getItem("phx:theme") || "system");
28	        }
29	        window.addEventListener("storage", (e) => e.key === "phx:theme" && setTheme(e.newValue || "system"));
30	        
31	        window.addEventListener("phx:set-theme", (e) => setTheme(e.target.dataset.phxTheme));
32	
33	        matchMedia("(prefers-color-scheme: dark)").addEventListener("change", (e) => {
34	          if (document.documentElement.getAttribute("data-theme-source") === "system") {
35	            document.documentElement.setAttribute("data-theme", systemTheme());
36	          }
37	        });
38	      })();
39	    </script>
40	  </head>
41	  <body>
42	    <ul class="menu menu-horizontal w-full relative z-10 flex items-center gap-4 px-4 sm:px-6 lg:px-8 justify-end">
43	      <%= if @current_scope do %>
44	        <li>
45	          {@current_scope.user.email}
46	        </li>
47	        <li>
48	          <.link href={~p"/users/settings"}>Settings</.link>
49	        </li>
50	        <li>
51	          <.link href={~p"/users/log-out"} method="delete">Log out</.link>
52	        </li>
53	      <% else %>
54	        <li>
55	          <.link href={~p"/users/register"}>Register</.link>
56	        </li>
57	        <li>
58	          <.link href={~p"/users/log-in"}>Log in</.link>
59	        </li>
60	      <% end %>
61	    </ul>
62	    {@inner_content}
63	    <%= if assigns[:socket] do %>
64	      <.live_component
65	        module={CleanerCrmWeb.FeedbackWidget}
66	        id="codemyspec-feedback"
67	        current_scope={assigns[:current_scope]}
68	      />
69	    <% end %>
70	  </body>
71	</html>
